const state={lang:preferences.lang==='en'?'en':'th',theme:preferences.theme==='dark'?'dark':'light',collapsed:!!preferences.collapsed,nodes:[],pending:[],events:[],policy:{discovery:'review',offline:'keep'}};
let config={visible_slots:[1],discovery:'review',offline:'keep'},snapshot=null,connected=false,lastFetch=0,started=false,session=null,page='overview',selected=null,filter='all',range='30m',historyCache={},life=null,polling=false,pollPromise=null,writeEpoch=0,toastTimer,commandPending=new Map();
