const btn=(label,action,cls='',ico='',attrs='')=>!isAdmin()&&writeActions.has(action)?'':`<button type="button" class="button ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${esc(label)}</button>`;
const isAdmin=()=>session?.channel==='local'&&session?.access==='admin',node=id=>state.nodes.find(n=>n.id===+id),name=n=>n.name&& !/^(ขัด|เครื่องขัด|Whitener)\s*\d+$/.test(n.name)?n.name:`${t('machine')} ${n.id}`;
const statusKey=n=>n.status==='empty'?'emptyStatus':n.status;
const statusIcon=s=>({run:'check',rest:'pause',alarm:'alert',warn:'alert',offline:'unlink',learn:'clock',unknown:'unlink',empty:'plus',fault:'alert',warning:'alert',normal:'check',learning:'clock'}[s]||'link');
const badge=n=>{const a=assess(n);return `<span class="badge tone-${a.level==='normal'&&n.status==='rest'?'rest':a.level}">${icon(statusIcon(a.level))}${esc(a.title)}</span>`;};

Object.assign(dict.th,{attentionTitle:'พบปัญหาที่ต้องตรวจสอบ',attentionNone:'ยังไม่พบปัญหาที่ต้องตรวจสอบ',attentionMachines:'เครื่องต้องตรวจสอบ',attentionAll:'ดูเครื่องที่ต้องตรวจทั้งหมด',inspection:'ดูวิธีตรวจ',faultLabel:'ขัดข้อง · FAULT',signalGood:'ได้รับข้อมูล',signalFault:'สัญญาณมีปัญหา',signalWarning:'ควรตรวจสัญญาณ',signalUnknown:'ยังยืนยันสัญญาณไม่ได้',sourceHub:'สถานะจาก Hub',eventStale:'อัปเดตประวัติไม่ได้ แสดงข้อมูลที่ได้รับก่อนหน้า',issueRestored:'สถานะปัญหาเปลี่ยนแล้ว กรุณาตรวจข้อมูลล่าสุด',allHealthy:'ไม่มีข้อขัดข้องที่ Hub รายงานในเครื่องที่ติดตาม',unknownCount:'ยังยืนยันไม่ได้',hubAttention:'Hub รายงานปัญหา',hubAction:'ดูการเชื่อมต่อและข้อมูลระบบ',moreIssues:'ปัญหาอื่น',noAlarmInference:'แจ้งปัญหาของระบบตรวจวัด แยกจาก Alarm ของกระบวนการ'});
Object.assign(dict.en,{attentionTitle:'Issues need your attention',attentionNone:'No issues requiring attention',attentionMachines:'machines need a check',attentionAll:'View all affected machines',inspection:'Inspect issue',faultLabel:'Equipment fault · FAULT',signalGood:'Data received',signalFault:'Signal fault',signalWarning:'Check signal',signalUnknown:'Signal unconfirmed',sourceHub:'Reported by Hub',eventStale:'History could not refresh. Showing previously received events.',issueRestored:'Issue status changed. Review the latest information.',allHealthy:'No equipment faults reported for tracked machines',unknownCount:'Unconfirmed',hubAttention:'Hub health issue',hubAction:'Check connections and system information',moreIssues:'other issues',noAlarmInference:'Measurement-system fault, separate from a process Alarm.'});
