async function loadHistory(id) {
 const epoch=writeEpoch, requestedRange=range, mac=node(id)?.mac, key=id+'-'+requestedRange;
 if(historyCache[key]?.loading)return;
 const entry=historyCache[key]={...historyCache[key],loading:true};
 const current=()=>historyCache[key]===entry&&epoch===writeEpoch&&node(id)?.mac===mac;
 try {
  const payload=await read(`/api/node/${id}/history?minutes=${requestedRange==='30m'?30:requestedRange==='1h'?60:480}`);
  if(!current())return;
  if(!Array.isArray(payload.points))throw Error('Invalid history response');
  Object.assign(entry,{points:M.normalizeHistory(payload),bucket_s:payload.bucket_s,receivedAt:Date.now(),failed:false});
 } catch {
  if(!current())return;
  entry.failed=true;
 } finally {
  entry.loading=false;
 }
 if(page!=='detail'||selected!==id||range!==requestedRange)return;
 if(!hasEditingFocus())render(true);
 else if(entry.failed) {
  const status=$('.chart-history-status');
  if(status)status.innerHTML=historyStatus(entry);
 }
}
let chartPoints=[];
function chart(n){const hist=historyCache[n.id+'-'+range],pts=hist?.points;const status=`<div class="chart-history-status" role="status">${historyStatus(hist)}</div>`;if(!pts)return status+(hist?.failed?'':`<div class="empty">${t('loading')}</div>`);if(!pts.some(p=>p.a!=null||p.b!=null))return status+`<div class="empty">${t('chartEmpty')}</div>`;chartPoints=pts;const values=pts.flatMap(p=>[p.a,p.b]).filter(Number.isFinite),max=Math.max(1,...values)*1.1,min=0,W=720,H=220,first=pts[0].ts,last=pts.at(-1).ts;function path(key){let d='',on=false,previous=null;for(const p of pts){if(previous!==null&&p.ts-previous>(hist.bucket_s||60)*1.5)on=false;previous=p.ts;if(!Number.isFinite(p[key])){on=false;continue;}const x=44+(p.ts-first)/Math.max(1,last-first)*660,y=190-(p[key]-min)/(max-min)*170;d+=`${on?'L':'M'}${x.toFixed(1)},${y.toFixed(1)} `;on=true;}return d;}return status+`<div class="chart-interactive" tabindex="0" role="slider" aria-label="${t('trend')}" aria-valuemin="1" aria-valuemax="${pts.length}" aria-valuenow="1"><svg class="chart" viewBox="0 0 ${W} ${H}" aria-hidden="true">${[0,.5,1].map(f=>`<line x1="44" x2="705" y1="${190-f*170}" y2="${190-f*170}"/><text x="4" y="${194-f*170}">${(f*max).toFixed(2)}</text>`).join('')}<path d="${path('a')}" fill="none" stroke="var(--green)" stroke-width="2"/>${pts.some(p=>p.b!=null)?`<path d="${path('b')}" fill="none" stroke="var(--blue)" stroke-width="2" stroke-dasharray="5 3"/>`:''}<text x="44" y="216">${clock(first*1000)}</text><text x="640" y="216">${clock(last*1000)}</text><line class="chart-cursor" x1="44" x2="44" y1="20" y2="190" visibility="hidden"/></svg><div class="chart-tooltip" hidden></div></div><div class="chart-key"><span><i></i>Pickup</span>${pts.some(p=>p.b!=null)?'<span><i></i>Piezo</span>':''}</div>`;}
function showChartPoint(wrap,index) {
 const svg=wrap.querySelector('.chart'),tip=wrap.querySelector('.chart-tooltip');
 const point=chartPoints[index],first=chartPoints[0].ts,last=chartPoints.at(-1).ts;
 const matrix=svg.getScreenCTM();if(!matrix)return;
 if(!tip.hidden&&Number(wrap.getAttribute('aria-valuenow'))===index+1)return;
 const cursorX=44+(point.ts-first)/Math.max(1,last-first)*660;
 const line=svg.querySelector('.chart-cursor');
 line.setAttribute('x1',cursorX);line.setAttribute('x2',cursorX);line.setAttribute('visibility','visible');
 const screen=svg.createSVGPoint();screen.x=cursorX;screen.y=20;
 const offset=screen.matrixTransform(matrix).x-wrap.getBoundingClientRect().left;
 const value=v=>Number.isFinite(v)?v.toFixed(2):(state.lang==='th'?'ไม่มีข้อมูล':'No data');
 tip.textContent=`${when(point.ts)} · Pickup: ${value(point.a)} · Piezo: ${value(point.b)}`;
 wrap.setAttribute('aria-valuenow',index+1);
 wrap.setAttribute('aria-valuetext',tip.textContent);
 tip.hidden=false;
 tip.style.left=`${Math.max(0,Math.min(wrap.clientWidth-tip.offsetWidth,offset-tip.offsetWidth/2))}px`;
}
function selectChartPoint(e) {
 const svg=e.target.closest('.chart-interactive .chart');if(!svg||!chartPoints.length)return;
 const matrix=svg.getScreenCTM();if(!matrix)return;
 const position=svg.createSVGPoint();position.x=e.clientX;position.y=e.clientY;
 const x=Math.max(44,Math.min(704,position.matrixTransform(matrix.inverse()).x));
 const first=chartPoints[0].ts,last=chartPoints.at(-1).ts,target=first+(x-44)/660*(last-first);
 const index=chartPoints.reduce((best,p,i)=>Math.abs(p.ts-target)<Math.abs(chartPoints[best].ts-target)?i:best,0);
 showChartPoint(svg.parentElement,index);
}
function hideChartPoint(wrap) {
 wrap.querySelector('.chart-tooltip').hidden=true;
 wrap.querySelector('.chart-cursor').setAttribute('visibility','hidden');
}
document.addEventListener('pointermove',e=>{if(e.pointerType!=='touch')selectChartPoint(e);});
document.addEventListener('click',e=>{if(e.detail)selectChartPoint(e);});
document.addEventListener('pointerout',e=>{
 const wrap=e.target.closest('.chart-interactive');
 if(wrap&&e.pointerType!=='touch'&&document.activeElement!==wrap&&!wrap.contains(e.relatedTarget))hideChartPoint(wrap);
});
document.addEventListener('pointerdown',e=>{
 const wrap=$('.chart-interactive');
 if(wrap&&!wrap.contains(e.target))hideChartPoint(wrap);
});
document.addEventListener('focusin',e=>{
 if(e.target.matches('.chart-interactive'))showChartPoint(e.target,Number(e.target.getAttribute('aria-valuenow'))-1);
});
document.addEventListener('focusout',e=>{if(e.target.matches('.chart-interactive'))hideChartPoint(e.target);});
document.addEventListener('keydown',e=>{
 const wrap=e.target.closest('.chart-interactive');if(!wrap)return;
 const index=Number(wrap.getAttribute('aria-valuenow'))-1,last=chartPoints.length-1;
 if(e.key==='Escape'){hideChartPoint(wrap);return;}
 const next={ArrowLeft:index-1,ArrowDown:index-1,ArrowRight:index+1,ArrowUp:index+1,Home:0,End:last}[e.key];
 if(next===undefined)return;
 e.preventDefault();showChartPoint(wrap,Math.max(0,Math.min(last,next)));
});
