async function pollAccess(){if(!isAdmin()||accessBusy||document.hidden)return;accessBusy=true;try{accessData=await read('/auth/access');accessFailed=false;}catch{accessData=null;accessFailed=true;}finally{accessBusy=false;const el=$('#access-panel'),active=document.activeElement;if(el&&!active?.matches('#mill-code')&&!pointerActive&&!keyActive){const action=el.contains(active)?active?.dataset?.action:null,id=active?.dataset?.id;el.outerHTML=accessMarkup();if(action){const target=[...document.querySelectorAll('#access-panel [data-action]')].find(b=>b.dataset.action===action&&b.dataset.id===id);(target||document.querySelector('[data-action="access-refresh"]'))?.focus({preventScroll:true});}}}}
