/* ---------- floor shell (approved mock v15) ---------- */
const navWords={th:{overview:'ภาพรวม',guide:'แจ้งเตือน',history:'เหตุการณ์',maintenance:'ตะแกรง',daily:'สรุปรายวัน',settings:'ตั้งค่า',support:'ติดต่อผู้ดูแล'},en:{overview:'Overview',guide:'Alarms',history:'Events',maintenance:'Screen care',daily:'Daily summary',settings:'Settings',support:'Support'}};
const navIcons={overview:'grid',guide:'alert',history:'history',maintenance:'screen',daily:'chart',settings:'settings',support:'headset'};
function shellSide(){const w=navWords[state.lang],count=attentionItems().length,pages=['overview','guide','history','maintenance','daily',...(isAdmin()?['settings']:[])];
 const current=page==='detail'?'overview':page,who=session?.user?.full_name||t('site');
 return `<aside class="gg-side" aria-label="${t('menu')}"><div class="gg-brand"><img src="assets/brand/grainguard-product-96.webp" alt=""><div><b>GrainGuard</b><small>by PumpkinTec</small></div></div>
 <nav class="gg-nav" aria-label="${t('menu')}">${pages.map(p=>`<button type="button" data-action="nav" data-page="${p}" ${current===p?'aria-current="page"':''}>${icon(navIcons[p])}<span>${w[p]}</span>${p==='guide'&&count?`<span class="gg-count">${count}</span>`:''}</button>`).join('')}</nav>
 <div class="gg-side-foot"><nav class="gg-nav" aria-label="${w.support}"><button type="button" data-action="nav" data-page="support" ${page==='support'?'aria-current="page"':''}>${icon('headset')}<span>${w.support}</span></button></nav>
 <button type="button" class="gg-user" data-action="profile" aria-label="${t('role')}"><span class="gg-avatar">${icon('user')}</span><span><b>${esc(who)}</b><small>${esc(isAdmin()?(state.lang==='en'?'Local administrator':'ผู้ดูแล Local'):(state.lang==='en'?'Online · view only':'Online · ดูอย่างเดียว'))}</small></span></button></div></aside>`;}
function hubLights(){const h=snapshot?.hub,live=state.nodes.filter(n=>n.status!=='empty'),on=live.filter(n=>!['offline','unknown'].includes(n.status)).length,net=h?.internet?.state;
 return {hub:connected?'ok':'bad',node:!connected?'off':on<live.length?'warn':'ok',on,total:live.length,mqtt:!connected?'off':h?.mqtt?'ok':'warn',cloud:!connected||!net||net==='unconfigured'?'off':['ok','online','connected','up'].includes(net)?'ok':'warn',net};}
function shellHead(){const L=hubLights(),en=state.lang==='en',sound=!!globalThis.GGBrowserAlarm?.enabled();
 const date=new Date().toLocaleDateString(en?'en-GB':'th-TH',{weekday:'short',day:'numeric',month:'short',year:'numeric',timeZone:snapshot?.hub?.tz||'Asia/Bangkok'});
 return `<header class="gg-head"><div class="gg-head-l"><b>${esc(t('site'))}</b><span class="gg-muted">${esc(isAdmin()?(en?'Local · on site':'Local · ในโรงสี'):(en?'Online · view only':'Online · ดูอย่างเดียว'))}</span>${siteModeBadge()}</div>
 <div class="gg-head-r"><div class="gg-links"><span><i class="gg-led ${L.hub}"></i>Hub</span><span><i class="gg-led ${L.node}"></i>Node <b class="num">${connected?L.on+'/'+L.total:'—'}</b></span><span><i class="gg-led ${L.mqtt}"></i>MQTT</span><span><i class="gg-led ${L.cloud}"></i>Cloud</span></div><span class="gg-sep"></span>
 <button type="button" class="gg-ibtn" data-action="sound" aria-pressed="${sound}" aria-label="${en?'Alarm sound on this screen':'เสียงเตือนเฉพาะหน้าจอนี้'}" title="${en?'Alarm sound on this screen':'เสียงเตือนเฉพาะหน้าจอนี้'}">${icon(sound?'bell':'belloff')}</button>
 <button type="button" id="language" class="gg-ibtn gg-txt" data-action="language" aria-label="${state.lang==='th'?'Switch to English':'เปลี่ยนเป็นภาษาไทย'}">${state.lang==='th'?'TH':'EN'}</button>
 <button type="button" class="gg-ibtn" data-action="theme" aria-label="${t('theme')}">${icon(state.theme==='dark'?'sun':'moon')}</button><span class="gg-sep"></span>
 <div class="gg-clockbox">${icon('clock')}<div><strong id="header-clock">${clock()}</strong><small>${esc(date)}</small></div></div></div><span id="connection-label" class="gg-sr" role="status"></span></header>`;}
function alarmBanner(){if(!connected)return '';const items=attentionItems().filter(({node:n,assessment:a})=>a.level==='alarm'&&!n.ack);if(!items.length)return '';
 const {node:n,assessment:a}=items[0],en=state.lang==='en';
 return `<div class="gg-banner" role="alert">${icon('alert')}<b>${esc(name(n))}</b><span class="gg-banner-msg">${esc(a.title)}${a.summary?' · '+esc(a.summary):''}${items.length>1?` · +${items.length-1}`:''}</span><span class="gg-banner-r">${n.since?`<span class="num">${en?'Since':'เริ่ม'} ${clock(n.since*1000)}</span>`:''}${isAdmin()?`<button type="button" class="gg-solid" data-action="ack" data-id="${n.id}">${esc(t('ack'))}</button>`:''}<button type="button" class="gg-ghost" data-action="detail" data-id="${n.id}">${en?'View machine':'ดูเครื่อง'}</button></span></div>`;}
// Keep the header lights and the alarm banner current without re-rendering the page, so focus stays put.
function patchShell(){const tpl=document.createElement('template');tpl.innerHTML=shellHead();const links=document.querySelector('.gg-links'),next=tpl.content.querySelector('.gg-links');if(links&&next&&links.innerHTML!==next.innerHTML)links.innerHTML=next.innerHTML;
 const ban=document.querySelector('.gg-banner'),nb=alarmBanner();if(ban&&!nb)ban.remove();else if(nb){if(!ban)document.querySelector('.gg-head')?.insertAdjacentHTML('afterend',nb);else if(ban.outerHTML!==nb)ban.outerHTML=nb;}}
function wearOf(n){const m=(life?.machines||[]).find(x=>Number(x.n)===n.id),p=m?.state?.used_pct;return Number.isFinite(p)?p:null;}
function sysGrid(){const L=hubLights(),h=snapshot?.hub,en=state.lang==='en';
 const cpu=Number.isFinite(h?.cpu_temp)?` · CPU ${h.cpu_temp.toFixed(1)}°C`:'';
 return `<div class="gg-sys"><div><i class="gg-led ${L.hub}"></i><span>Hub<small>${connected?esc((h?.id||'Pi')+cpu):t('hubLost')}</small></span></div><div><i class="gg-led ${L.node}"></i><span>Node<small class="num">${connected?`${L.on} / ${L.total} ${en?'sending':'ส่งข้อมูล'}`:'—'}</small></span></div><div><i class="gg-led ${L.mqtt}"></i><span>MQTT<small>${connected?t(h?.mqtt?'healthy':'unhealthy'):'—'}</small></span></div><div><i class="gg-led ${L.cloud}"></i><span>Cloud<small>${!connected?'—':!L.net||L.net==='unconfigured'?t('unconfigured'):esc(L.net)}</small></span></div></div>`;}
const feedKind=type=>/^(ALARM|SHADOW_ALARM|ACK)/.test(type)?['alarm','alert']:/^(FAULT|HEALTH)/.test(type)?['fault','wrench']:type==='SCREEN_CHANGE'?['screen','screen']:/^(CMD|ASSIGN|CAL|MODE|RECORD)/.test(type)?['','settings']:['','link'];
function feed(){return feedRows(trackedEvents().slice(0,5));}
// Fixed 1920 × 1080 stage scaled to the screen (Pi kiosk 1360 × 850 window, TVs). Narrow screens use the flowing layout.
function fitStage(){const w=innerWidth,h=innerHeight-(document.querySelector('#offline-fixture-banner')?.offsetHeight||0);document.body.style.zoom=w>=1100?String(Math.min(w/1920,h/1080)):'';}
addEventListener('resize',fitStage);
setTimeout(()=>loadLife().then(()=>{if(page==='overview'&&!hasEditingFocus())render(true);}),1200);
setInterval(()=>{if(!document.hidden)loadLife();},60000);

/* ---------- sensor helpers shared by the overview cards and the node page ---------- */
// One place decides a sensor's light, label and whether it is the cause. Evidence comes only from the Hub:
// the alarm channel reported by the Node (A/B/AB) or a sensor-health issue on that channel.
function sensorState(n,ch){
 const val=ch==='a'?n.a:n.b,a=assess(n),signal=a.channels[ch],disabled=ch==='b'&&connected&&!['offline','unknown','empty'].includes(n.status)&&n.raw&&n.chb===false;
 const label=disabled?t('notEnabled'):t(signal==='fault'?'signalFault':signal==='warning'?'signalWarning':signal==='normal'?'signalGood':'signalUnknown');
 const alarmHot=n.status==='alarm'&&!!n.alarmCh&&n.alarmCh.includes(ch.toUpperCase()),sensorHot=signal==='fault'||signal==='warning';
 const code=(n.codes||[]).find(c=>ch==='a'?/^E10\d$/.test(c):/^E11\d$/.test(c));
 return {val,signal,disabled,label,hot:alarmHot||sensorHot,alarmHot,fault:!alarmHot&&sensorHot,
  tag:alarmHot?(state.lang==='en'?'Cause':'ต้นเหตุ'):code||(state.lang==='en'?'Check':'ตรวจ'),
  led:disabled?'off':alarmHot||signal==='fault'?'bad':signal==='warning'?'warn':signal==='normal'?'ok':''};
}
// Per-sensor history chart for the node page. Real Hub buckets only; gaps longer than 1.5 buckets stay gaps.
function sensorChart(n,key){
 const hist=historyCache[n.id+'-'+range],pts=hist?.points,en=state.lang==='en';
 if(!pts)return `<div class="gg-chart-msg">${hist?.failed?esc(historyStatus(hist)):t('loading')}</div>`;
 const vals=pts.map(p=>p[key]).filter(Number.isFinite);
 if(vals.length<2)return `<div class="gg-chart-msg">${key==='b'&&n.chb===false?t('notEnabled'):t('chartEmpty')}</div>`;
 const W=900,H=270,L=48,R=12,T=12,B=30,first=pts[0].ts,last=pts.at(-1).ts,span=Math.max(1,last-first);
 const top=Math.max(...vals),step=top>2?1:top>1?.5:.25,max=Math.max(step*2,Math.ceil(top*1.08/step)*step),ticks=[];for(let v=0;v<=max+1e-9;v+=step)ticks.push(+v.toFixed(2));
 const X=ts=>L+(ts-first)/span*(W-L-R),Y=v=>T+(H-T-B)*(1-v/max),gap=(hist.bucket_s||60)*1.5;
 const segs=[];let cur=[],prev=null;for(const p of pts){if(prev!==null&&p.ts-prev>gap&&cur.length){segs.push(cur);cur=[];}prev=p.ts;if(Number.isFinite(p[key]))cur.push(p);else if(cur.length){segs.push(cur);cur=[];}}if(cur.length)segs.push(cur);
 const lines=segs.map(sg=>{const d=sg.map((p,i)=>`${i?'L':'M'}${X(p.ts).toFixed(1)} ${Y(p[key]).toFixed(1)}`).join('');return `<path d="${d}L${X(sg.at(-1).ts).toFixed(1)} ${Y(0)}L${X(sg[0].ts).toFixed(1)} ${Y(0)}Z" fill="var(--gg-chart-fill)"/><path d="${d}" fill="none" stroke="var(--gg-chart)" stroke-width="2" vector-effect="non-scaling-stroke"/>`;}).join('');
 const end=segs.at(-1)?.at(-1),xs=[0,.25,.5,.75,1].map(f=>first+f*span);
 const grid=ticks.map(v=>`<line x1="${L}" x2="${W-R}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--gg-grid)"/><text x="${L-8}" y="${Y(v)+5}" text-anchor="end">${v}</text>`).join('');
 const xl=xs.map((ts,i)=>`<text x="${X(ts)}" y="${H-6}" text-anchor="${i===0?'start':i===xs.length-1?'end':'middle'}">${clock(ts*1000).slice(0,5)}</text>`).join('');
 return `<svg class="gg-chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${key==='a'?'Pickup':'Piezo'} ${en?'history':'ย้อนหลัง'}">${grid}${lines}${end?`<circle cx="${X(end.ts)}" cy="${Y(end[key])}" r="5" fill="var(--gg-chart)" stroke="var(--gg-panel)" stroke-width="2"/>`:''}${xl}</svg>`;
}
// Feed rows used by the overview side panel and the node page.
function feedRows(list){return list.map(e=>{const [cls,ic]=feedKind(e.type||'');return `<li><span class="gg-fi ${cls}">${icon(ic)}</span><b>${esc(eventMachine(e))}</b><time>${e.ts?clock(e.ts*1000):''}</time><p>${esc(eventText(e))}</p></li>`;}).join('')||`<li class="gg-none">${t('noEvents')}</li>`;}

/* ---------- daily summary ---------- */
let dailyData=null,errorsData=null,dailyFailed=false,dailyDate=null;
async function loadDaily(){try{[dailyData,errorsData]=await Promise.all([read('/api/daily?days=14'),read('/api/errors')]);dailyFailed=false;}catch{dailyFailed=!dailyData;}if(page==='daily'&&!hasEditingFocus())render(true);}
function dailyPage(){return GGDailyView.render({daily:dailyData,errors:errorsData,nodes:state.nodes,lang:state.lang,date:dailyDate,icon,failed:dailyFailed});}
setInterval(()=>{if(page==='daily'&&!document.hidden)loadDaily();},60000);
Object.assign(dict.th,{daily:'สรุปรายวัน'});Object.assign(dict.en,{daily:'Daily summary'});
